"use client";

import { useRef, useState, type FormEvent } from "react";
import { vendorCategories, vendorSchema, type VendorInput } from "@/modules/vendors/schemas";
import styles from "./vendors.module.css";

type Vendor = VendorInput & { id: string; source: "MANUAL" | "GOOGLE_PLACES"; archivedAt: string | null; revision: number };
type Page = { data: Vendor[]; pagination: { page: number; limit: number; total: number; totalPages: number } };
type Summary = { count: number; totalAgreedCostPaise: number; categoryCount: number; byCategory: { category: string; count: number }[] };
type EventOption = { id: string; name: string; archived: boolean };
const money = (paise: number | null) => paise === null ? "Not recorded" : new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR" }).format(paise / 100);
const label = (value: string) => value.split("_").map((part) => part.charAt(0) + part.slice(1).toLowerCase()).join(" ");
class RequestError extends Error { constructor(message: string, readonly code?: string) { super(message); } }
async function responseJson(response: Response) { const json = await response.json(); if (!response.ok) throw new RequestError(json.error?.message || "Something went wrong. Please try again.", json.error?.code); return json; }
function parseAmount(value: string) { if (!value.trim()) return null; if (!/^\d{1,10}(\.\d{1,2})?$/.test(value)) return NaN; const [rupees, paise = ""] = value.split("."); return Number(rupees) * 100 + Number(paise.padEnd(2, "0")); }

export default function VendorsPanel({ initial, initialSummary, events }: { initial: Page; initialSummary: Summary; events: EventOption[] }) {
  const [page, setPage] = useState(initial); const [summary, setSummary] = useState(initialSummary);
  const [category, setCategory] = useState(""); const [search, setSearch] = useState(""); const [includeArchived, setIncludeArchived] = useState(false);
  const [editing, setEditing] = useState<Vendor | null>(null); const [formKey, setFormKey] = useState(0); const [error, setError] = useState(""); const [formError, setFormError] = useState(""); const [busy, setBusy] = useState(false);
  const dialog = useRef<HTMLDialogElement>(null);
  async function load(target: number, refreshSummary = false) {
    const query = new URLSearchParams({ page: String(target), limit: "20" }); if (category) query.set("category", category); if (search.trim()) query.set("search", search.trim()); if (includeArchived) query.set("includeArchived", "true");
    const result: Page = await responseJson(await fetch(`/api/vendors?${query}`, { cache: "no-store" }));
    if (target > Math.max(1, result.pagination.totalPages)) return load(Math.max(1, result.pagination.totalPages), refreshSummary);
    setPage(result); if (refreshSummary) setSummary((await responseJson(await fetch("/api/vendors/summary", { cache: "no-store" }))).data);
  }
  async function refresh(target: number, refreshSummary = false) { setError(""); setBusy(true); try { await load(target, refreshSummary); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load vendors."); } finally { setBusy(false); } }
  async function openForm(vendor: Vendor | null) {
    setError("");
    if (vendor) { setBusy(true); try { vendor = (await responseJson(await fetch(`/api/vendors/${vendor.id}`, { cache: "no-store" }))).data as Vendor; const latest = vendor; setPage((current) => ({ ...current, data: current.data.map((item) => item.id === latest.id ? latest : item) })); } catch (reason) { setError(reason instanceof RequestError && reason.code === "NOT_FOUND" ? "This vendor is no longer available. Refresh the list to see the latest records." : "Could not load the latest vendor. Please try again."); setBusy(false); return; } setBusy(false); }
    setEditing(vendor); setFormError(""); setFormKey((key) => key + 1); dialog.current?.showModal();
  }
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setFormError(""); const form = new FormData(event.currentTarget); const eventIds = form.getAll("eventIds").map(String);
    const parsed = vendorSchema.safeParse({ name: form.get("name"), category: form.get("category"), contactPerson: form.get("contactPerson"), phone: form.get("phone"), email: form.get("email"), address: form.get("address"), website: form.get("website"), totalAgreedCostPaise: parseAmount(String(form.get("totalAgreedCost") ?? "")), eventIds, notes: form.get("notes") });
    if (!parsed.success) { setFormError(parsed.error.issues[0]?.message || "Please check the form."); return; }
    setBusy(true); try { await responseJson(await fetch(editing ? `/api/vendors/${editing.id}` : "/api/vendors", { method: editing ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(editing ? { ...parsed.data, expectedRevision: editing.revision } : parsed.data) })); dialog.current?.close(); await load(editing ? page.pagination.page : 1, true); }
    catch (reason) { if (reason instanceof RequestError && reason.code === "CONFLICT" && editing) { try { await load(page.pagination.page, true); setFormError("This vendor changed. Your draft is still here; close the form and reopen the vendor to review the latest version."); } catch { setFormError("This vendor changed and the list could not be refreshed. Your draft is still here; close the form and try opening the vendor again."); } } else { setFormError(reason instanceof Error ? reason.message : "Unable to save vendor."); } } finally { setBusy(false); }
  }
  async function archive(vendor: Vendor) { if (!window.confirm(`Archive “${vendor.name}”? Existing expense history will be retained.`)) return; setBusy(true); setError(""); try { await responseJson(await fetch(`/api/vendors/${vendor.id}`, { method: "DELETE" })); await load(page.pagination.page, true); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to archive vendor."); } finally { setBusy(false); } }
  return <div className={styles.page}>
    <header className={styles.heading}><div><p className={styles.eyebrow}>Wedding planning · Your private space</p><h1>My vendors</h1><p>Keep every wedding partner, contact, and commitment in one thoughtful place.</p></div><button type="button" className={styles.primary} disabled={busy} onClick={() => void openForm(null)}>+ Add vendor</button></header>
    <div className={styles.privacy}><span aria-hidden="true">◇</span><div><strong>Private to your planning team</strong><p>Vendor records and agreed costs are visible only to wedding admins and managers.</p></div></div>
    <section className={styles.summary} aria-label="Vendor summary"><div className={styles.totalCard}><span className={styles.cardLabel}>Active vendors</span><strong>{summary.count}</strong><p>Partners saved for your celebrations.</p></div><div className={styles.countCard}><span className={styles.cardLabel}>Agreed cost recorded</span><strong>{money(summary.totalAgreedCostPaise)}</strong><p>Only the amounts you choose to record.</p></div><div className={styles.categoryCard}><span className={styles.cardLabel}>Categories represented</span><strong>{summary.categoryCount}</strong><p>{summary.byCategory.length ? summary.byCategory.map((row) => `${label(row.category)} (${row.count})`).join(" · ") : "Your vendor categories will appear here."}</p></div></section>
    <section className={styles.panel} aria-labelledby="vendor-list-heading"><div className={styles.panelHeader}><div><h2 id="vendor-list-heading">Vendor directory</h2><p>A clear record of the people and teams supporting your wedding.</p></div><span>{page.pagination.total} {page.pagination.total === 1 ? "vendor" : "vendors"}</span></div>
      <form className={styles.filters} onSubmit={(event) => { event.preventDefault(); void refresh(1); }}><label>Search<input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Vendor name" /></label><label>Category<select value={category} onChange={(event) => setCategory(event.target.value)}><option value="">All categories</option>{vendorCategories.map((item) => <option key={item} value={item}>{label(item)}</option>)}</select></label><label className={styles.archiveToggle}><input type="checkbox" checked={includeArchived} onChange={(event) => setIncludeArchived(event.target.checked)} /> Include archived</label><button className={styles.secondary} disabled={busy}>Apply</button></form>
      {error && <p className={styles.error} role="alert">{error}</p>}
      <div className={styles.tableWrap}><table className={styles.table}><thead><tr><th scope="col">Vendor</th><th scope="col">Contact</th><th scope="col">Related events</th><th scope="col" className={styles.amount}>Agreed cost</th><th scope="col" className={styles.actions}>Actions</th></tr></thead><tbody>{page.data.map((vendor) => <tr key={vendor.id}><td data-label="Vendor"><strong>{vendor.name}</strong><span className={styles.category}>{label(vendor.category)}</span>{vendor.archivedAt && <span className={styles.archived}>Archived</span>}{vendor.notes && <span className={styles.notes}>{vendor.notes}</span>}</td><td data-label="Contact">{vendor.contactPerson && <strong>{vendor.contactPerson}</strong>}<span>{vendor.phone || vendor.email || "No contact details"}</span>{vendor.phone && vendor.email && <span>{vendor.email}</span>}</td><td data-label="Related events">{vendor.eventIds.length ? <div className={styles.tags}>{vendor.eventIds.map((eventId) => { const item = events.find((value) => value.id === eventId); return <span key={eventId}>{item ? `${item.name}${item.archived ? " (Archived)" : ""}` : "Unavailable event"}</span>; })}</div> : "General wedding"}</td><td data-label="Agreed cost" className={styles.amount}><strong>{money(vendor.totalAgreedCostPaise)}</strong></td><td data-label="Actions" className={styles.actions}><button type="button" aria-label={`Edit ${vendor.name}`} onClick={() => void openForm(vendor)} disabled={busy}>Edit</button>{!vendor.archivedAt && <button type="button" aria-label={`Archive ${vendor.name}`} onClick={() => void archive(vendor)} disabled={busy}>Archive</button>}</td></tr>)}</tbody></table></div>
      {!page.data.length && <div className={styles.empty}><strong>No vendors found</strong><p>Add your first vendor or adjust your filters to see records here.</p><button type="button" className={styles.secondary} onClick={() => void openForm(null)}>Add your first vendor</button></div>}
      <div className={styles.pagination}><span>Page {page.pagination.page} of {Math.max(1, page.pagination.totalPages)}</span><div><button type="button" onClick={() => void refresh(page.pagination.page - 1)} disabled={busy || page.pagination.page <= 1}>Previous</button><button type="button" onClick={() => void refresh(page.pagination.page + 1)} disabled={busy || page.pagination.page >= page.pagination.totalPages}>Next</button></div></div>
    </section>
    <dialog ref={dialog} className={styles.dialog} aria-labelledby="vendor-form-heading"><form key={formKey} onSubmit={save} className={styles.form}><div className={styles.formHeading}><div><p className={styles.eyebrow}>My vendors</p><h2 id="vendor-form-heading">{editing ? "Edit vendor" : "Add vendor"}</h2><p>Keep the details you need close at hand.</p></div><button type="button" className={styles.close} onClick={() => dialog.current?.close()} aria-label="Close form"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17" /></svg></button></div>
      <label>Vendor name <input name="name" required maxLength={160} defaultValue={editing?.name} placeholder="e.g. Malabar Frames Photography" /></label><div className={styles.formGrid}><label>Category <select name="category" defaultValue={editing?.category ?? "PHOTOGRAPHER"}>{vendorCategories.map((item) => <option key={item} value={item}>{label(item)}</option>)}</select></label><label>Contact person <input name="contactPerson" maxLength={120} defaultValue={editing?.contactPerson} placeholder="Name of your point of contact" /></label></div><div className={styles.formGrid}><label>Phone <input name="phone" maxLength={40} inputMode="tel" defaultValue={editing?.phone} placeholder="+91 98765 43210" /></label><label>Email <input name="email" type="email" maxLength={254} defaultValue={editing?.email} placeholder="hello@example.com" /></label></div><label>Address <input name="address" maxLength={500} defaultValue={editing?.address} placeholder="Venue or business address" /></label><div className={styles.formGrid}><label>Website <input name="website" type="url" maxLength={2048} defaultValue={editing?.website} placeholder="https://example.com" /></label><label>Total agreed cost (₹) <input name="totalAgreedCost" inputMode="decimal" defaultValue={editing?.totalAgreedCostPaise === null || editing?.totalAgreedCostPaise === undefined ? "" : (editing.totalAgreedCostPaise / 100).toFixed(2)} placeholder="Optional" /></label></div><fieldset className={styles.eventChoices}><legend>Related events</legend><p>Link this vendor to the events they support.</p>{events.filter((item) => !item.archived || editing?.eventIds.includes(item.id)).map((item) => <label key={item.id}><input type="checkbox" name="eventIds" value={item.id} defaultChecked={editing?.eventIds.includes(item.id)} /> {item.name}{item.archived ? " (Archived)" : ""}</label>)}</fieldset><label>Notes <textarea name="notes" maxLength={2000} rows={4} defaultValue={editing?.notes} placeholder="Add any helpful details" /></label>{formError && <p role="alert" className={styles.error}>{formError}</p>}<div className={styles.formActions}><button type="button" className={styles.secondary} onClick={() => dialog.current?.close()}>Cancel</button><button type="submit" className={styles.primary} disabled={busy}>{busy ? "Saving…" : "Save vendor"}</button></div></form></dialog>
  </div>;
}
